import{_ as e,o as r,c as a,a5 as o}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"useStorage实现","description":"1. 思想总览 步骤 关键点 说明 ① 读取初始值 storage.getItem(key) 如果有 → 反序列化得到初始值；没有 → 用 defaultValue 并 写回 storage。 ② 建立响应式 const data ref(initial) 得到可写的 Ref\\\\<。","frontmatter":{"title":"useStorage实现","date":"2026-08-11T00:00:00.000Z","categories":["React 系统教程"],"tags":["React","Redux","前端","教程","OneNote","性能与实战"],"description":"1. 思想总览 步骤 关键点 说明 ① 读取初始值 storage.getItem(key) 如果有 → 反序列化得到初始值；没有 → 用 defaultValue 并 写回 storage。 ② 建立响应式 const data ref(initial) 得到可写的 Ref\\\\<。","sidebarWeight":20,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/应用/持久化的响应式状态/useStorage实现.md"},"headers":[],"relativePath":"posts/React系统教程/05-性能与实战/持久化的响应式状态/useStorage实现.md","filePath":"posts/React系统教程/05-性能与实战/持久化的响应式状态/useStorage实现.md"}'),s={name:"posts/React系统教程/05-性能与实战/持久化的响应式状态/useStorage实现.md"};function n(g,t,l,i,d,u){return r(),a("div",null,[...t[0]||(t[0]=[o('<div><h1 id="usestorage实现" tabindex="-1">useStorage实现 <a class="header-anchor" href="#usestorage实现" aria-label="Permalink to &quot;useStorage实现&quot;">​</a></h1><blockquote><p>本节目标：理解“useStorage实现”的核心思路，并能把它用于实际开发或面试表达。 <strong>1. 思想总览</strong></p></blockquote><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>步骤</strong></td><td><strong>关键点</strong></td><td><strong>说明</strong></td></tr><tr><td>① 读取初始值</td><td>storage.getItem(key)</td><td>如果有 → 反序列化得到初始值；没有 → 用 defaultValue 并<strong>写回</strong> storage。</td></tr><tr><td>② 建立响应式</td><td>const data = ref(initial)</td><td>得到可写的 Ref&lt;T&gt;。</td></tr><tr><td>③ 写 ↔️ storage 同步</td><td>watch(data, …)</td><td>数据变化 → storage.setItem(key, serialize(value))。</td></tr><tr><td>④ storage → 写回</td><td>监听浏览器 &quot;storage&quot; 事件，实现<strong>多 Tab 同步</strong>。</td><td></td></tr><tr><td>⑤ 可切换存储源</td><td>第三参数 storage = localStorage</td><td>也可传 sessionStorage、customStorage 等。</td></tr><tr><td>⑥ 序列化策略</td><td>内置 <strong>智能序列化器</strong></td><td>根据 defaultValue 类型自动选 JSON / number / boolean；支持自定义 options.serializer。</td></tr><tr><td>⑦ 作用域自动清理</td><td>tryOnScopeDispose()</td><td>组件卸载时注销 &quot;storage&quot; 事件监听。</td></tr></tbody></table><p>官方文档速览 <a href="https://vueuse.org/core/usestorage/?utm_source=chatgpt.com" target="_blank" rel="noreferrer">VueUse</a><strong>2. 精简版源码（带全注释，可直接复制）</strong><strong>提示</strong>：若你已安装 @vueuse/core，直接阅读 node_modules/@vueuse/core/useStorage/index.ts 即可；下面代码与官方一致，只删去类型工具与 polyfill，保留核心逻辑与注释。</p><p>ts 复制编辑 import { ref, Ref, watch, isRef, toValue, // VueUse 辅助：同时兼容 ref / 普通值 tryOnScopeDispose // 组件卸载感知} from &#39;vue&#39;import { useEventListener } from &#39;@vueuse/core&#39; // 自己用的监听工具 /* ---------- 1. 辅助：序列化器 ---------- <em>/export interface Serializer&lt;T = any&gt; { read(raw: string | null): T write(value: T): string} /</em> 默认序列化器集合（会根据 defaultValue 类型自动选用） <em>/export const StorageSerializers = { /</em>* boolean &lt;-&gt; &quot;true&quot;/&quot;false&quot; <em>/ boolean: &lt;Serializer&lt;boolean&gt;&gt;{ read: (v) =&gt; v === &#39;true&#39;, write: (v) =&gt; String(v) }, /</em>* number &lt;-&gt; &quot;123&quot; <em>/ number: &lt;Serializer&lt;number&gt;&gt;{ read: (v) =&gt; v === null ? NaN : Number(v), write: (v) =&gt; String(v) }, /</em>* any JSON-compatible value <em>/ object: &lt;Serializer&lt;any&gt;&gt;{ read: (v) =&gt; v ? JSON.parse(v) : null, write: (v) =&gt; JSON.stringify(v) }, /</em>* string &lt;-&gt; string <em>/ string: &lt;Serializer&lt;string&gt;&gt;{ read: (v) =&gt; v ?? &#39;&#39;, write: (v) =&gt; String(v) }} as const /</em> ---------- 2. 主函数 useStorage ---------- <em>/export interface UseStorageOptions&lt;T&gt; { /</em>* 自定义序列化器 <em>/ serializer?: Serializer&lt;T&gt; /</em>* 是否监听其它窗口对同 key 的修改（默认 true） <em>/ listenToStorageChanges?: boolean /</em>* 钩子：写入前的自定义转换 <em>/ writeDefaults?: boolean} export function useStorage&lt;T&gt;( key: string, defaultValue: T, storage: Storage | undefined = localStorage, options: UseStorageOptions&lt;T&gt; = {}): Ref&lt;T&gt; { const { serializer = guessSerializer(defaultValue), listenToStorageChanges = true, writeDefaults = true } = options /</em> ---------- 2.1 读取初始值 ---------- <em>/ function read(event?: StorageEvent): T { // 如果来了 storage 事件，且 key 不匹配则忽略 if (event &amp;&amp; event.key !== key) return toValue(data) try { const raw = storage?.getItem(key) if (raw == null) { // 本地没有，写入默认值 if (writeDefaults &amp;&amp; defaultValue != null) storage?.setItem(key, serializer.write(defaultValue)) return defaultValue } else return serializer.read(raw) } catch (e) { console.error(&#39;[useStorage] read error&#39;, e) return defaultValue } } /</em> ---------- 2.2 创建 Ref 并初始化 ---------- <em>/ const data = ref&lt;T&gt;(read()) as Ref&lt;T&gt; /</em> ---------- 2.3 响应式写回 storage ---------- <em>/ watch( data, (val) =&gt; { try { if (val == null) storage?.removeItem(key) else storage?.setItem(key, serializer.write(val)) } catch (e) { // 容量超限或 Safari 隐私模式等错误 console.error(&#39;[useStorage] write error&#39;, e) } }, { deep: true } ) /</em> ---------- 2.4 跨标签页同步 ---------- <em>/ if (listenToStorageChanges &amp;&amp; typeof window !== &#39;undefined&#39;) { useEventListener(window, &#39;storage&#39;, read) } /</em> ---------- 2.5 卸载时清理 ---------- <em>/ tryOnScopeDispose(() =&gt; { if (listenToStorageChanges &amp;&amp; typeof window !== &#39;undefined&#39;) window.removeEventListener(&#39;storage&#39;, read as any) }) return data} /</em> ---------- 3. 根据 defaultValue 猜测序列化器 ---------- */function guessSerializer&lt;T&gt;(value: T): Serializer&lt;T&gt; { switch (typeof value) { case &#39;boolean&#39;: return StorageSerializers.boolean as any case &#39;number&#39;: return StorageSerializers.number as any case &#39;string&#39;: return StorageSerializers.string as any case &#39;object&#39;: return StorageSerializers.object as any default: return StorageSerializers.string as any }}</p><p><strong>3. 使用示例（同步 localStorage）</strong></p><p>ts 复制编辑 import { useStorage } from &#39;@vueuse/core&#39; export const userToken = useStorage(&#39;token&#39;, &#39;&#39;) // stringexport const darkMode = useStorage(&#39;dark&#39;, false) // booleanexport const cart = useStorage(&#39;cart&#39;, []) // object / array</p><ul><li><strong>取值</strong>：cart.value</li><li><strong>赋值</strong>：cart.value.push(item) → 自动写入 localStorage</li><li><strong>跨标签同步</strong>：另一个 Tab 修改后，这里能立即响应。</li></ul><p><strong>4. 自定义场景</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>场景</strong></td><td><strong>代码</strong></td></tr><tr><td>使用 sessionStorage</td><td>useStorage(&#39;key&#39;, 0, sessionStorage)</td></tr><tr><td>禁用跨标签同步</td><td>useStorage(&#39;k&#39;, true, localStorage, { listenToStorageChanges: false })</td></tr><tr><td>自定义序列化器（例如 comma-list）</td><td>ts const comma = { read: (v)=&gt;v.split(&#39;,&#39;), write:(v)=&gt;v.join(&#39;,&#39;) } useStorage(&#39;ids&#39;, [&#39;1&#39;], localStorage, { serializer: comma })</td></tr></tbody></table><p><strong>小结</strong></p><ul><li>useStorage() <strong>“一行代码”</strong> 把普通 ref 升级为 <strong>自动持久化</strong> + <strong>跨窗口同步</strong> 的高级 ref。</li><li>内部只有 <strong>~150 行</strong> TypeScript，阅读成本低；掌握后可按需裁剪或改写（如切换到 IndexedDB、加加密等）。</li></ul><p>希望这份“原理 + 源码”能让你彻底掌握 useStorage() 的底层实现及扩展方式！</p></div>',1)])])}const S=e(s,[["render",n]]);export{m as __pageData,S as default};
